<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { House, User, Bell, List, Connection, VideoPlay, ArrowRight, Plus, Search, Refresh, SwitchButton, Close, Phone, Check, Warning, Location, DataAnalysis, Clock, ArrowLeft, ChatLineRound, SetUp } from '@element-plus/icons-vue'
import * as echarts from 'echarts'
import AgentWorkspace from './AgentWorkspace.vue'
import AgentRunDetail from './AgentRunDetail.vue'

type Row = Record<string, any>
const token=ref(sessionStorage.getItem('linan_token')||'')
const me=ref<Row|null>(null), page=ref('overview'), loading=ref(false), busy=ref(false)
const elders=ref<Row[]>([]), incidents=ref<Row[]>([]), tasks=ref<Row[]>([]), staff=ref<Row[]>([]), notifications=ref<Row[]>([])
const username=ref('admin'), password=ref('Demo2026!'), search=ref(''), filter=ref('all')
const selected=ref<Row|null>(null), detail=ref(false), elderDetail=ref<Row|null>(null)
const reportOpen=ref(false), report=ref<Row>({elder_id:1,kind:'safe',note:'',hours:4,count15:0,count60:0,gap:60})
const profileOpen=ref(false), profile=ref<Row>({name:'',age:75,building:'1号楼 · 101',contact:'',routine:'07:00 起床，22:00 休息',checkin_hour:9})
const recOpen=ref(false), recommendations=ref<Row[]>([]), unassigned=ref<string[]>([])
const actionOpen=ref(false), actionTask=ref<Row|null>(null), actionKind=ref('feedback'), outcome=ref('safe'), actionNote=ref('')
const experiments=ref<Row|null>(null), experimentBusy=ref(false), replayElder=ref(2), replayOffset=ref(0), replayInfo=ref<Row|null>(null)
const chartEl=ref<HTMLElement>(), chart=ref<echarts.ECharts>(), noticeOpen=ref(false)
const isAdmin=computed(()=>me.value?.role==='admin')
const baselineReady=(e:Row)=>e.profile.history_days>=14&&e.profile.baseline_ready!==false
const isOperator=computed(()=>['admin','staff'].includes(me.value?.role||''))
const roleNames:Record<string,string>={admin:'社区管理人员',staff:'社区照护人员',family:'关联家属',elder:'老人本人'}
const levelNames:Record<number,string>={'-1':'平稳',0:'状态未知',1:'关注',2:'优先',3:'紧急'}
const stateNames:Record<string,string>={pending:'待确认',dispatched:'已派单',accepted:'已接单',processing:'处理中',review:'待复核',closed:'已关闭'}
const skillNames:Record<string,string>={phone:'电话核实',visit:'上门走访',device:'设备检查'}
const kindNames:Record<string,string>={safe:'报平安',contact:'请求联系',sos:'主动求助',away:'确认外出',home:'确认在家',rest:'确认休息',need_help:'需要帮助',unreachable:'核实未获回应',data_offline:'数据源离线',data_online:'数据源恢复',missed_checkin:'未按约定报平安',activity:'活动窗口'}
const navs=computed(()=>isAdmin.value?[
 {key:'overview',label:'守护总览',en:'Overview',icon:House},{key:'elders',label:'老人档案与状态',en:'Residents',icon:User},
 {key:'incidents',label:'风险事件',en:'Risk events',icon:Bell},{key:'tasks',label:'任务中心',en:'Care tasks',icon:List},
 {key:'staff',label:'人员资源',en:'Care team',icon:Connection},{key:'assistant',label:'邻安助手',en:'Care assistant',icon:ChatLineRound},
 {key:'workflows',label:'工作流中心',en:'Agent workflows',icon:SetUp},{key:'lab',label:'回放与实验',en:'Replay & evaluation',icon:DataAnalysis}
]:me.value?.role==='staff'?[
 {key:'tasks',label:'我的任务',en:'My care tasks',icon:List},{key:'elders',label:'服务对象',en:'Residents',icon:User},{key:'staff',label:'我的状态',en:'Availability',icon:Connection},{key:'assistant',label:'邻安助手',en:'Care assistant',icon:ChatLineRound}
]:[{key:'care',label:'安心守护',en:'My care',icon:House},{key:'incidents',label:'状态记录',en:'Care updates',icon:Bell},{key:'assistant',label:'邻安助手',en:'Care assistant',icon:ChatLineRound}])
const currentTitle=computed(()=>navs.value.find(n=>n.key===page.value)?.label||'守护总览')
const openIncidents=computed(()=>incidents.value.filter(i=>i.status==='open'))
const activeTasks=computed(()=>tasks.value.filter(t=>t.state!=='closed'))
const urgent=computed(()=>openIncidents.value.filter(i=>i.level>=2))
const available=computed(()=>staff.value.filter(w=>w.on_duty&&w.available&&!w.busy))
const sortedElders=computed(()=>[...elders.value].sort((a,b)=>b.level-a.level||a.id-b.id))
const filteredElders=computed(()=>sortedElders.value.filter(e=>(!search.value||`${e.name} ${e.building}`.includes(search.value))&&(filter.value==='all'||String(e.level)===filter.value)))
const filteredIncidents=computed(()=>incidents.value.filter(i=>(filter.value==='all'||i.status===filter.value)&&(!search.value||`${i.elder_name} ${i.title}`.includes(search.value))))
const filteredTasks=computed(()=>tasks.value.filter(t=>(filter.value==='all'||t.state===filter.value)&&(!search.value||`${t.elder_name} ${t.id} ${t.title}`.includes(search.value))))
const today=computed(()=>new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}))
const reportKinds=computed(()=>Object.entries(kindNames).filter(([k])=>isOperator.value||['safe','contact','sos','away','home','rest'].includes(k)))
const fmt=(n:number)=>n?new Date(n*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'暂无记录'
const ageMinutes=(n:number)=>Math.max(0,Math.floor((Date.now()/1000-n)/60))

async function api(path:string,options:RequestInit={}) {
 const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...options.headers}})
 const data=await r.json()
 if(!r.ok){
  if(r.status===401&&path!=='/auth/login'){token.value='';me.value=null;sessionStorage.removeItem('linan_token')}
  const message=typeof data.detail==='string'?data.detail:'请检查输入内容后重试'
  throw new Error(message)
 }
 return data
}
const post=(path:string,body:Row={})=>api(path,{method:'POST',body:JSON.stringify(body)})
async function execute(fn:()=>Promise<unknown>,success?:string) {
 busy.value=true
 try{await fn();if(success)ElMessage.success(success)}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}
}
async function login(account?:string) {
 loading.value=true
 try{
  const result=await post('/auth/login',{username:account||username.value,password:account?'Demo2026!':password.value})
  token.value=result.token;sessionStorage.setItem('linan_token',result.token);me.value=result.user
  page.value=result.user.role==='admin'?'overview':result.user.role==='staff'?'tasks':'care'
  selected.value=null;detail.value=false;recommendations.value=[];recOpen.value=false
  await refresh()
 }catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}
}
async function logout(){try{await post('/auth/logout')}finally{me.value=null;token.value='';sessionStorage.removeItem('linan_token')}}
async function refresh() {
 if(!token.value)return
 const paths=['/elders','/incidents','/notifications',...(isOperator.value?['/tasks','/staff']:[])]
 const data=await Promise.all(paths.map(p=>api(p)))
 elders.value=data[0];incidents.value=data[1];notifications.value=data[2];tasks.value=data[3]||[];staff.value=data[4]||[]
 await nextTick();drawChart()
}
function drawChart(){
 if(!chartEl.value||page.value!=='overview')return
 if(!chart.value)chart.value=echarts.init(chartEl.value)
 chart.value.setOption({animationDuration:450,grid:{top:24,right:12,bottom:28,left:36},tooltip:{trigger:'axis'},
  xAxis:{type:'category',data:elders.value.map(e=>e.name.slice(0,1)+e.name.slice(-1)),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#7a8983',fontSize:10,interval:1}},
  yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf1ed',type:'dashed'}},axisLabel:{color:'#8a9790',fontSize:10}},
  series:[{name:'近15分钟活动次数（合成快照）',type:'bar',data:elders.value.map(e=>({value:e.state.count15,itemStyle:{color:e.level>=2?'#d58b66':e.level===1?'#c4ad66':'#5f9885'}})),barMaxWidth:15,itemStyle:{borderRadius:[4,4,0,0]}}]})
}
async function showElder(e:Row){await execute(async()=>{elderDetail.value=await api('/elders/'+e.id);selected.value=null;detail.value=true})}
async function showTask(t:Row){await execute(async()=>{selected.value=await api('/tasks/'+t.id);elderDetail.value=null;detail.value=true})}
async function showIncident(i:Row){
 const task=tasks.value.find(t=>t.incident_id===i.id)
 if(task)await showTask(task)
 else{selected.value={...i,incident_id:i.id};elderDetail.value=null;detail.value=true}
}
async function openAgentCitation(citation:Row){
 if((citation.type==='task'||citation.task_id)&&isOperator.value){await showTask({id:citation.task_id||citation.id});return}
 if(citation.type==='incident'){
  const incident=incidents.value.find(i=>i.id===citation.id)
  if(incident){await showIncident(incident);return}
 }
 const elder=elders.value.find(e=>e.id===Number(citation.elder_id||(citation.type==='elder'?citation.id:0)))
 if(elder){await showElder(elder);return}
 ElMessage.info('依据记录：'+(citation.label||citation.id))
}
function openReport(eid?:number,kind='safe'){report.value={elder_id:eid||elders.value[0]?.id||1,kind,note:'',hours:4,count15:0,count60:0,gap:60};reportOpen.value=true}
async function sendReport(){await execute(async()=>{
 const r=report.value;const payload:Row={note:r.note}
 if(['away','rest','home'].includes(r.kind))payload.hours=r.hours
 if(r.kind==='activity')Object.assign(payload,{count15:r.count15,count60:r.count60,gap:r.gap})
 await post('/events',{elder_id:r.elder_id,kind:r.kind,source:roleNames[me.value!.role]+'上报',payload});reportOpen.value=false;await refresh()
},'信息已记录，系统已更新判断')}
function editProfile(e?:Row){profile.value=e?{id:e.id,name:e.name,age:e.age,building:e.building,contact:e.contact,routine:e.profile.routine,checkin_hour:e.profile.checkin_hour}:{name:'',age:75,building:'1号楼 · 101',contact:'',routine:'07:00 起床，22:00 休息',checkin_hour:9};profileOpen.value=true}
async function saveProfile(){await execute(async()=>{await api('/elders'+(profile.value.id?'/'+profile.value.id:''),{method:profile.value.id?'PUT':'POST',body:JSON.stringify(profile.value)});profileOpen.value=false;await refresh()},'档案已保存')}
async function recommend(){await execute(async()=>{const r=await post('/dispatch/recommend');recommendations.value=r.recommendations.map((x:Row)=>({...x,chosen:x.staff_id,reason:''}));unassigned.value=r.unassigned;recOpen.value=true})}
async function confirmRec(r:Row){await execute(async()=>{
 await post('/dispatch/confirm',{recommendation_id:r.id,staff_id:r.chosen,reason:r.reason});recommendations.value=recommendations.value.filter(x=>x.id!==r.id);await refresh()
},'派单已确认')}
async function simpleAction(t:Row,action:string){await execute(async()=>{await post('/tasks/'+t.id+'/action',{action});await refresh();if(detail.value)selected.value=await api('/tasks/'+t.id)},'任务状态已更新')}
function openAction(t:Row,action:string){actionTask.value=t;actionKind.value=action;outcome.value='safe';actionNote.value='';actionOpen.value=true}
async function sendAction(){await execute(async()=>{await post('/tasks/'+actionTask.value!.id+'/action',{action:actionKind.value,outcome:outcome.value,note:actionNote.value});actionOpen.value=false;await refresh();if(detail.value)selected.value=await api('/tasks/'+actionTask.value!.id)},'处置记录已保存')}
async function updateWorker(w:Row){await execute(async()=>{await api('/staff/'+w.id,{method:'PUT',body:JSON.stringify({on_duty:!!w.on_duty,available:!!w.available,location:w.location})});await refresh()},'人员状态已更新')}
async function scenario(name:string){await execute(async()=>{await post('/demo/scenario',{scenario:name,elder_id:replayElder.value});await refresh()},'合成情景已回放')}
async function runExperiment(){experimentBusy.value=true;try{experiments.value=await post('/experiments/run')}catch(e){ElMessage.error((e as Error).message)}finally{experimentBusy.value=false}}
async function replayWindow(){await execute(async()=>{replayInfo.value=await post('/replay/window',{elder_id:replayElder.value,offset:replayOffset.value});replayOffset.value++;await refresh()},'公开数据窗口已映射到当前演示时间')}
function downloadJson(name:string,data:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function exportFeedback(){await execute(async()=>downloadJson('linan-reviewed-feedback.json',await api('/feedback/export')))}
let interval:ReturnType<typeof setInterval>
watch(page,async()=>{search.value='';filter.value='all';if(chart.value){chart.value.dispose();chart.value=undefined}await nextTick();drawChart();if(page.value==='lab'&&isAdmin.value){try{experiments.value=await api('/experiments')}catch{}}})
const resize=()=>chart.value?.resize()
onMounted(async()=>{
 if(token.value){try{me.value=await api('/me');page.value=isAdmin.value?'overview':me.value?.role==='staff'?'tasks':'care';await refresh()}catch{me.value=null}}
 interval=setInterval(()=>{if(me.value&&!busy.value)refresh().catch(()=>{})},5000);window.addEventListener('resize',resize)
})
onUnmounted(()=>{clearInterval(interval);chart.value?.dispose();window.removeEventListener('resize',resize)})
</script>

<template>
 <div v-if="!me" class="login-page">
  <div class="login-story"><div class="brand"><span class="brand-symbol"><el-icon><House/></el-icon></span><b>邻安<span>LINAN CARE</span></b></div><div class="login-copy"><span class="eyebrow">让守护有依据，让关怀有回应</span><h1>一个社区的力量，<br>守护每一户安心。</h1><p>从状态发现到协同处置，让每一次关注<br>都能抵达需要帮助的人。</p><div class="architecture"><span>感知</span><i>→</i><span>判断</span><i>→</i><span>决策</span><i>→</i><span>反馈</span></div></div><p class="login-foot">独居老人社区协同守护智能决策系统 · 比赛原型</p></div>
  <div class="login-panel"><div class="login-form"><span class="eyebrow green">COMMUNITY CARE WORKSPACE</span><h2>欢迎回到邻安</h2><p class="muted">登录工作台，开启今天的社区守护。</p><el-form @submit.prevent="login()" label-position="top"><el-form-item label="账号"><el-input v-model="username" size="large" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password size="large" autocomplete="current-password" @keyup.enter="login()"/></el-form-item><el-button type="primary" size="large" class="full" :loading="loading" @click="login()">登录守护工作台 <el-icon><ArrowRight/></el-icon></el-button></el-form><div class="demo-login"><span>快速体验演示身份</span><div><el-button @click="login('admin')" :disabled="loading">社区管理员</el-button><el-button @click="login('staff1')" :disabled="loading">照护人员</el-button><el-button @click="login('family')" :disabled="loading">家属</el-button><el-button @click="login('elder')" :disabled="loading">老人</el-button></div><small>演示密码 Demo2026! · 仅使用虚拟档案</small></div></div></div>
 </div>
 <div v-else class="app-shell">
  <aside class="sidebar"><div class="brand"><span class="brand-symbol"><el-icon><House/></el-icon></span><b>邻安<span>LINAN CARE</span></b></div><div class="workspace-label">社区协同守护平台</div><nav><button v-for="n in navs" :key="n.key" :aria-label="n.label" :title="n.label" :class="{active:page===n.key}" @click="page=n.key"><el-icon><component :is="n.icon"/></el-icon><span>{{n.label}}<small>{{n.en}}</small></span><b v-if="n.key==='tasks'&&activeTasks.length" class="nav-count">{{activeTasks.length}}</b></button></nav><div class="sidebar-bottom"><div class="local-status"><i/> 本地演示运行中</div><p>公开数据与仿真情景分开验证<br>每一次决策均可追溯</p><div class="community-badge"><el-icon><Location/></el-icon><div>安和社区<small>20 位虚拟老人 · 演示环境</small></div></div></div></aside>
  <main class="main"><header class="topbar"><div class="breadcrumb">安和社区 <span>/</span> <b>{{currentTitle}}</b></div><div class="top-actions"><span class="system-status"><i/> 服务在线</span><button class="icon-btn" aria-label="查看站内消息" @click="noticeOpen=true"><el-icon><Bell/></el-icon><span v-if="notifications.length" class="notice-dot"/></button><div class="top-divider"/><span class="avatar">{{me.name.slice(0,1)}}</span><div class="user-caption"><b>{{me.name}}</b><small>{{roleNames[me.role]}}</small></div><button class="icon-btn" aria-label="退出并切换身份" @click="logout"><el-icon><SwitchButton/></el-icon></button></div></header>
   <div class="content">
    <div class="page-heading"><div><span class="eyebrow green">{{navs.find(n=>n.key===page)?.en.toUpperCase()}}</span><h1>{{currentTitle}}</h1><p>{{page==='overview'?'看见需要，判断轻重，让每一份关怀及时抵达。':page==='tasks'?'从待确认到已关闭，让每次处置都有回应。':page==='lab'?'把判断过程重放，把决策效果量化。':'信息有来源，判断有依据，行动有记录。'}}</p></div><div class="heading-actions"><span class="date-label">{{today}}</span><el-button :icon="Refresh" @click="execute(refresh)" :loading="busy">刷新</el-button><el-button v-if="page==='elders'&&isAdmin" type="primary" :icon="Plus" @click="editProfile()">建立档案</el-button><el-button v-if="page!=='lab'" type="primary" :icon="Plus" @click="openReport()">信息上报</el-button></div></div>

    <AgentWorkspace :key="me.username" v-show="page==='assistant'||page==='workflows'" :view="page==='workflows'?'workflows':'assistant'" :active="page==='assistant'||page==='workflows'" :user="me" :elders="elders" :tasks="tasks" :api="api" @navigate="openAgentCitation" @changed="execute(refresh)"/>

    <template v-if="page==='overview'">
     <section class="hero"><div><span class="hero-kicker"><i/> 今日守护正在进行</span><h2>每一次及时响应，<br>都有据可循。</h2><p>当前有 <b>{{urgent.length}}</b> 条优先或紧急事件需要关注，<br>系统已准备好协同处置建议。</p><el-button class="hero-button" @click="recommend">查看派单建议 <el-icon><ArrowRight/></el-icon></el-button></div><div class="hero-illustration" aria-hidden="true"><div class="orbit orbit-one"/><div class="orbit orbit-two"/><div class="home-figure"><el-icon><House/></el-icon><span>安和社区</span><small>CONNECTED WITH CARE</small></div><div class="float-note note-a"><i class="dot green-dot"/> 个人状态 · 持续关注</div><div class="float-note note-b"><el-icon><Check/></el-icon> 协同处置 · 形成闭环</div><div class="tiny-home home-a"><el-icon><House/></el-icon></div><div class="tiny-home home-b"><el-icon><House/></el-icon></div></div><div class="hero-index">01 <span>/ COMMUNITY GUARD</span></div></section>
     <div class="stats-grid"><div class="stat-card"><div><span>守护中的老人</span><el-icon><User/></el-icon></div><strong>{{elders.length}}<small>位</small></strong><p><i class="dot green-dot"/> 全部为虚拟演示档案</p></div><div class="stat-card"><div><span>待关注事件</span><el-icon><Bell/></el-icon></div><strong>{{openIncidents.length}}<small>条</small></strong><p><span class="warm-text">{{urgent.length}} 条优先或紧急</span> · {{openIncidents.filter(i=>i.level===0).length}} 条数据待核实</p></div><div class="stat-card"><div><span>处置中的任务</span><el-icon><List/></el-icon></div><strong>{{activeTasks.length}}<small>项</small></strong><p>{{tasks.filter(t=>t.state==='pending').length}} 项待确认 · {{tasks.filter(t=>t.overdue&&t.state!=='closed').length}} 项超时</p></div><div class="stat-card"><div><span>当前可用人员</span><el-icon><Connection/></el-icon></div><strong>{{available.length}}<small>/ {{staff.length}} 人</small></strong><p><i class="dot green-dot"/> 技能、值班与容量共同约束</p></div></div>
     <div class="dashboard-grid"><section class="panel priority-panel"><div class="panel-title"><div><h3>需要关注的老人 <span class="section-count">{{openIncidents.length}}</span></h3><p>按当前风险等级排序</p></div><button class="text-link" @click="page='incidents'">全部事件 <el-icon><ArrowRight/></el-icon></button></div><div v-for="e in sortedElders.filter(x=>x.level>=0).slice(0,5)" :key="e.id" class="priority-row"><div class="resident-avatar" :class="'tone-'+e.level">{{e.name.slice(0,1)}}</div><div class="resident-line"><b>{{e.name}}<small>{{e.age}} 岁 · {{e.building}}</small></b><span>{{incidents.find(i=>i.id===e.latest_incident)?.title}}</span></div><span class="risk-pill" :class="'level-'+e.level">{{levelNames[e.level]}}</span><button class="row-arrow" :aria-label="'查看'+e.name" @click="showElder(e)"><el-icon><ArrowRight/></el-icon></button></div><el-empty v-if="!openIncidents.length" description="当前没有待关注事件" :image-size="70"/><div class="panel-foot"><el-icon><Clock/></el-icon> 数据每 5 秒刷新 · 来源和判断依据可查看</div></section>
      <section class="panel team-panel"><div class="panel-title"><div><h3>协同照护力量</h3><p>让合适的人处理合适的任务</p></div><span class="outline-badge">{{available.length}} 人可用</span></div><div v-for="w in staff" :key="w.id" class="team-row"><span class="worker-avatar">{{w.name.slice(-1)}}</span><div><b>{{w.name}}</b><p>{{w.skills.map((s:string)=>skillNames[s]).join(' / ')}}</p></div><span class="staff-state" :class="{free:w.available&&w.on_duty&&!w.busy}"><i/>{{w.busy?'执行任务中':!w.on_duty?'未值班':w.available?'可分配':'暂不可用'}}</span></div><el-button class="full quiet-button" @click="page='staff'">管理人员状态 <el-icon><ArrowRight/></el-icon></el-button></section>
      <section class="panel chart-panel"><div class="panel-title"><div><h3>活动状态快照</h3><p>每位老人最近一个 15 分钟窗口的活动次数</p></div><span class="subtle-label">演示数据 · 非健康结论</span></div><div ref="chartEl" class="activity-chart"/></section><section class="panel closed-loop"><span class="eyebrow green">DECISION LOOP</span><h3>从发现，到回应。</h3><p>系统推荐，社区确认；<br>过程留痕，结果可复盘。</p><div class="loop-steps"><span>识别异常</span><i>→</i><span>协同处置</span><i>→</i><span>反馈复核</span></div><button class="text-link" @click="page='lab'">进入回放与实验 <el-icon><ArrowRight/></el-icon></button></section></div>
    </template>

    <template v-else-if="page==='elders'"><div class="toolbar"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索姓名、楼栋" clearable/><el-select v-model="filter"><el-option label="全部状态" value="all"/><el-option v-for="(v,k) in levelNames" :key="k" :label="v" :value="String(k)"/></el-select><span class="muted">共 {{filteredElders.length}} 位</span></div><div class="resident-grid"><article v-for="e in filteredElders" :key="e.id" class="panel resident-card"><div class="resident-card-top"><span class="resident-avatar large" :class="'tone-'+e.level">{{e.name.slice(0,1)}}</span><span class="risk-pill" :class="'level-'+e.level">{{levelNames[e.level]}}</span></div><h3>{{e.name}} <small>{{e.age}} 岁</small></h3><p>{{e.building}} · {{e.contact}}</p><div class="resident-metrics"><div><span>最近报平安</span><b>{{fmt(e.state.last_checkin)}}</b></div><div><span>个人活动基线</span><b>{{baselineReady(e)?'已建立':'学习中'}}</b></div></div><p class="data-caption"><i class="dot" :class="e.data_unknown?'amber-dot':'green-dot'"/>{{e.data_unknown?'活动数据待核实':e.state.source}}</p><div class="card-actions"><el-button @click="showElder(e)">查看档案</el-button><el-button v-if="isAdmin" @click="editProfile(e)" text>编辑</el-button><el-button text type="primary" @click="openReport(e.id)">上报</el-button></div></article></div><el-empty v-if="!filteredElders.length" description="暂无匹配档案；照护人员可查看分配任务关联的老人"/></template>

    <template v-else-if="page==='incidents'"><div class="toolbar"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索老人或事件" clearable/><el-select v-model="filter"><el-option label="全部事件" value="all"/><el-option label="待处理" value="open"/><el-option label="已关闭" value="closed"/></el-select></div><section class="panel table-panel"><el-table :data="filteredIncidents" @row-click="showIncident" class="clickable-table"><el-table-column label="关注对象" min-width="120"><template #default="{row}"><b>{{row.elder_name}}</b></template></el-table-column><el-table-column label="当前等级" width="110"><template #default="{row}"><span class="risk-pill" :class="'level-'+row.level">{{levelNames[row.level]}}</span></template></el-table-column><el-table-column prop="title" label="事件" min-width="180"/><el-table-column label="判断依据" min-width="270"><template #default="{row}"><span class="muted">{{row.evidence[0]}}</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{row.status==='open'?'待处理':'已关闭'}}</template></el-table-column><el-table-column label="更新时间" width="130"><template #default="{row}">{{fmt(row.updated)}}</template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button text type="primary" @click.stop="showIncident(row)">详情</el-button></template></el-table-column></el-table></section></template>

    <template v-else-if="page==='tasks'"><div class="task-summary"><span v-for="(label,key) in stateNames" :key="key" :class="{selected:filter===key}" @click="filter=filter===key?'all':String(key)">{{label}} <b>{{tasks.filter(t=>t.state===key).length}}</b></span></div><div class="toolbar"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索任务、老人姓名" clearable/><el-button v-if="isAdmin" type="primary" :icon="Connection" @click="recommend" :loading="busy">计算派单建议</el-button></div><div class="task-list"><section v-for="t in filteredTasks" :key="t.id" class="panel task-card"><div class="task-card-head"><span class="risk-pill" :class="'level-'+t.level">{{levelNames[t.level]}}</span><span class="task-id">{{t.id}}</span><span class="task-state" :class="{finished:t.state==='closed'}">{{stateNames[t.state]}}</span><span v-if="t.overdue&&t.state!=='closed'" class="overdue">已超时</span></div><h3>{{t.elder_name}} <small>· {{t.title}}</small></h3><p class="task-advice">{{t.advice}}</p><div class="task-meta"><span><el-icon><User/></el-icon>{{t.staff_name||'等待社区确认人员'}}</span><span><el-icon><Clock/></el-icon>创建于 {{fmt(t.created)}}</span><span>{{skillNames[t.required_skill]}}</span></div><div class="task-bottom"><span class="muted">{{t.state==='closed'?'处置已形成闭环':'持续跟进 · 判断与操作均留痕'}}</span><div><el-button @click="showTask(t)">详情与记录</el-button><el-button v-if="t.state==='dispatched'" type="primary" @click="simpleAction(t,'accept')">接单</el-button><el-button v-if="['dispatched','accepted'].includes(t.state)" @click="openAction(t,'reject')">拒单</el-button><el-button v-if="t.state==='accepted'" type="primary" @click="simpleAction(t,'start')">开始处理</el-button><el-button v-if="['accepted','processing'].includes(t.state)" type="primary" @click="openAction(t,'feedback')">提交处置结果</el-button><el-button v-if="isAdmin&&t.state==='review'" @click="simpleAction(t,'followup')">继续跟进</el-button><el-button v-if="isAdmin&&t.state!=='closed'" type="primary" plain @click="openAction(t,'close')">核实并关闭</el-button></div></div></section><el-empty v-if="!filteredTasks.length" description="当前没有此类任务"/></div></template>

    <template v-else-if="page==='staff'"><div class="info-banner"><el-icon><Connection/></el-icon><div><b>人员可用性会在确认派单时再次检查</b><p>每人同时执行一项任务。修改值班或可用状态后，已生成的推荐可能需要重新计算。</p></div></div><div class="staff-grid"><section v-for="w in staff" :key="w.id" class="panel worker-card"><div class="worker-card-top"><span class="worker-avatar large">{{w.name.slice(-1)}}</span><div><h3>{{w.name}}</h3><p>{{w.busy?'已有执行任务':w.on_duty&&w.available?'当前可分配':'当前不可分配'}}</p></div><span class="dot" :class="w.on_duty&&w.available&&!w.busy?'green-dot':'amber-dot'"/></div><div class="skill-list"><span v-for="s in w.skills" :key="s">{{skillNames[s]}}</span></div><div class="setting-line"><span>当前值班</span><el-switch v-model="w.on_duty" :active-value="1" :inactive-value="0" @change="updateWorker(w)"/></div><div class="setting-line"><span>接受新任务</span><el-switch v-model="w.available" :active-value="1" :inactive-value="0" @change="updateWorker(w)"/></div><div class="setting-line"><span>所在楼栋（仿真）</span><el-select v-model="w.location" @change="updateWorker(w)"><el-option v-for="n in 5" :key="n" :label="n+'号楼'" :value="n"/></el-select></div><p class="data-caption">{{w.active_task?'执行任务：'+w.active_task:'暂无执行中的任务'}}</p></section></div></template>

    <template v-else-if="page==='lab'"><div class="info-banner"><el-icon><DataAnalysis/></el-icon><div><b>两条验证线，分别报告结果</b><p>CASAS 单住户数据用于活动规律实验；社区派单使用虚拟老人、人员与时间矩阵。实验不推断真实社区效果。</p></div></div><div class="lab-grid"><section class="panel lab-card"><span class="eyebrow green">SCENARIO REPLAY</span><h3>把一次协同处置完整重放</h3><p class="muted">所有情景操作都会写入当前演示数据库，并保留判断和操作记录。</p><div class="lab-select"><span>情景关联老人</span><el-select v-model="replayElder"><el-option v-for="e in elders" :key="e.id" :label="e.name" :value="e.id"/></el-select></div><div class="scenario-grid"><button @click="scenario('story')" :disabled="busy"><el-icon><VideoPlay/></el-icon><b>三位老人，同时需要关注</b><span>未报平安 / 活动偏离 / 主动求助</span></button><button @click="scenario('offline')" :disabled="busy"><el-icon><Connection/></el-icon><b>数据源离线</b><span>显示未知，生成数据核查任务</span></button><button @click="scenario('away')" :disabled="busy"><el-icon><Location/></el-icon><b>确认外出</b><span>补充上下文，保留待核实事件</span></button><button @click="scenario('cold_start')" :disabled="busy"><el-icon><Clock/></el-icon><b>历史不足 14 天</b><span>基线学习中，保留上报规则</span></button><button @click="scenario('conflict')" :disabled="busy"><el-icon><Warning/></el-icon><b>多人求助与资源冲突</b><span>检验优先级、容量和任务保留</span></button><button @click="scenario('normal')" :disabled="busy"><el-icon><Check/></el-icon><b>收到报平安</b><span>补充核实证据，等待人工复核</span></button></div></section><section class="panel lab-card"><span class="eyebrow green">PUBLIC DATA REPLAY</span><h3>CASAS Aruba 活动窗口</h3><p class="muted">使用公开数据训练的基线和留出测试段回放。原始时间保留在事件中，演示观察时间映射为当前时间。</p><div class="lab-select"><span>测试段窗口偏移</span><el-input-number v-model="replayOffset" :min="0" :max="100000"/></div><el-button type="primary" :icon="VideoPlay" @click="replayWindow" :loading="busy">回放下一窗口</el-button><div v-if="replayInfo" class="replay-result"><b>窗口 {{replayInfo.offset}} / {{replayInfo.total}}</b><p>原始时间：{{fmt(replayInfo.original_timestamp)}}</p><p>近15分钟活动 {{replayInfo.count15}} 次 · 距上次活动 {{Number(replayInfo.gap).toFixed(1)}} 分钟</p><small>来源：CASAS Aruba · 在虚拟档案中回放</small></div><div class="lab-note"><b>可复现设计</b><p>按时间顺序 60% / 20% / 20% 划分。基线仅使用训练段，阈值仅使用验证段；测试段只做评估。</p></div><el-button @click="exportFeedback">导出已复核反馈</el-button></section></div>
     <section class="panel experiment-panel"><div class="panel-title"><div><h3>决策效果对比</h3><p>固定随机种子 42 · 结果由本机实际计算</p></div><div><el-button v-if="experiments" @click="downloadJson('linan-experiments.json',experiments)">导出结果</el-button><el-button type="primary" :icon="DataAnalysis" :loading="experimentBusy" @click="runExperiment">运行对比实验</el-button></div></div><el-empty v-if="!experiments" description="点击运行，生成活动识别与人员调度对比结果" :image-size="80"/><template v-else><div v-for="(a,key) in {synthetic:experiments.activity,...(experiments.casas?{casas:experiments.casas}:{})}" :key="key" class="experiment-block"><h4>{{key==='casas'?'公开数据 · CASAS Aruba':'合成数据 · 活动异常识别'}}</h4><p class="muted">训练 {{a.split.train}} / 验证 {{a.split.validation}} / 测试 {{a.split.test}} 个窗口</p><table class="metric-table"><thead><tr><th>方法</th><th>原始数据报警率</th><th>注入异常窗口召回</th><th>注入异常事件召回</th><th>检出事件平均延迟</th></tr></thead><tbody><tr v-for="(m,k) in {baseline:a.baseline,personalized:a.personalized}" :key="k"><td>{{k==='baseline'?'统一固定阈值':'个性化异常模型'}}</td><td>{{(m.original_alarm_rate*100).toFixed(1)}}%</td><td>{{(m.injected_window_recall*100).toFixed(1)}}%</td><td>{{(m.injected_episode_recall*100).toFixed(1)}}%</td><td>{{m.mean_detection_delay_minutes===null?'未检出':m.mean_detection_delay_minutes+' 分钟'}}</td></tr></tbody></table><p class="experiment-note">{{a.interpretation}}</p></div><div class="experiment-block"><h4>合成数据 · 社区任务调度</h4><table class="metric-table"><thead><tr><th>方法</th><th>平均响应时间</th><th>P95 响应时间</th><th>紧急任务30分钟覆盖率</th><th>约束违反</th></tr></thead><tbody><tr v-for="(m,k) in {baseline:experiments.scheduling.baseline,optimized:experiments.scheduling.optimized}" :key="k"><td>{{k==='baseline'?'先到先处理＋最近可用':'风险优先＋最小费用匹配'}}</td><td>{{m.mean_response_minutes}} 分钟</td><td>{{m.p95_response_minutes}} 分钟</td><td>{{(m.urgent_covered_within_30_minutes*100).toFixed(1)}}%</td><td>{{m.constraint_violations}}</td></tr></tbody></table><p class="experiment-note">{{experiments.scheduling.interpretation}}</p></div></template></section>
    </template>

    <template v-else-if="page==='care'"><section class="care-hero panel" v-for="e in elders" :key="e.id"><span class="eyebrow green">CONNECTED WITH CARE</span><h2>{{me.role==='elder'?'今天过得怎么样？':e.name+'的守护空间'}}</h2><p>最近报平安：{{fmt(e.state.last_checkin)}}</p><div class="care-status"><span class="risk-pill" :class="'level-'+e.level">{{levelNames[e.level]}}</span><span>{{e.data_unknown?'活动数据暂不可用，可通过报平安补充状态':'每一次回应，都让家人多一份安心。'}}</span></div><div class="care-buttons"><button class="care-safe" @click="openReport(e.id,'safe')"><el-icon><Check/></el-icon><b>我很平安</b><span>向家人与社区报平安</span></button><button class="care-contact" @click="openReport(e.id,'contact')"><el-icon><Phone/></el-icon><b>请联系我</b><span>有事情需要社区帮忙</span></button><button class="care-sos" @click="openReport(e.id,'sos')"><el-icon><Warning/></el-icon><b>我需要帮助</b><span>向社区发出主动求助</span></button></div><div class="context-buttons"><el-button size="large" @click="openReport(e.id,'away')">确认外出</el-button><el-button size="large" @click="openReport(e.id,'home')">确认在家</el-button><el-button size="large" @click="openReport(e.id,'rest')">确认休息</el-button></div><p class="data-caption">演示仅产生站内消息；求助处理记录由社区人员核实关闭。</p></section><section class="panel care-updates"><h3>最近状态记录</h3><div v-for="i in incidents.slice(0,6)" :key="i.id" class="care-update"><span class="risk-pill" :class="'level-'+i.level">{{levelNames[i.level]}}</span><div><b>{{i.title}}</b><p>{{i.advice}}</p></div><span class="muted">{{fmt(i.updated)}}</span></div><el-empty v-if="!incidents.length" description="暂无需要关注的记录"/></section></template>

    <footer class="page-footer"><span>邻安 LINAN CARE <i>·</i> 让关怀有回应</span><span>比赛原型 / 数据来源与模型版本均可追溯</span></footer>
   </div>
  </main>

  <el-dialog v-model="reportOpen" title="记录一条状态信息" width="min(540px, 94vw)"><el-form label-position="top"><el-form-item label="关联老人"><el-select v-model="report.elder_id" class="full"><el-option v-for="e in elders" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item label="信息类型"><el-select v-model="report.kind" class="full"><el-option v-for="[k,v] in reportKinds" :key="k" :label="v" :value="k"/></el-select></el-form-item><div v-if="report.kind==='sos'" class="sos-explain">确认后将生成紧急事件并提醒社区管理员。当前为站内消息演示。</div><el-form-item v-if="['away','home','rest'].includes(report.kind)" label="本次状态确认有效期（小时）"><el-input-number v-model="report.hours" :min="1" :max="24"/></el-form-item><div v-if="report.kind==='activity'" class="form-columns"><el-form-item label="15分钟活动次数"><el-input-number v-model="report.count15" :min="0"/></el-form-item><el-form-item label="60分钟活动次数"><el-input-number v-model="report.count60" :min="0"/></el-form-item><el-form-item label="距上次活动（分钟）"><el-input-number v-model="report.gap" :min="0"/></el-form-item></div><el-form-item label="补充说明"><el-input v-model="report.note" type="textarea" :rows="3" maxlength="1000" placeholder="例如：家属陪同外出，预计下午返回"/></el-form-item></el-form><template #footer><el-button @click="reportOpen=false">取消</el-button><el-button :type="report.kind==='sos'?'danger':'primary'" @click="sendReport" :loading="busy">确认上报</el-button></template></el-dialog>

  <el-dialog v-model="profileOpen" :title="profile.id?'编辑老人档案':'建立老人档案'" width="min(560px,94vw)"><el-form label-position="top"><div class="form-columns"><el-form-item label="姓名"><el-input v-model="profile.name"/></el-form-item><el-form-item label="年龄"><el-input-number v-model="profile.age" :min="60" :max="120"/></el-form-item></div><el-form-item label="楼栋与房间"><el-input v-model="profile.building"/></el-form-item><el-form-item label="联系人"><el-input v-model="profile.contact"/></el-form-item><el-form-item label="日常作息"><el-input v-model="profile.routine"/></el-form-item><el-form-item label="计划报平安时间（小时）"><el-input-number v-model="profile.checkin_hour" :min="0" :max="23"/></el-form-item><p class="muted">新档案初始无活动历史，显示基线学习中。</p></el-form><template #footer><el-button @click="profileOpen=false">取消</el-button><el-button type="primary" @click="saveProfile" :loading="busy">保存档案</el-button></template></el-dialog>

  <el-dialog v-model="recOpen" title="协同处置 · 派单建议" width="min(780px,95vw)"><p class="muted">风险与等待时间优先，技能、值班与空闲状态为硬约束。预计时间来自仿真矩阵。</p><section v-for="r in recommendations" :key="r.id" class="recommendation"><div><span class="risk-pill" :class="'level-'+r.level">{{levelNames[r.level]}}</span><b>{{tasks.find(t=>t.id===r.task_id)?.elder_name}} · {{tasks.find(t=>t.id===r.task_id)?.title}}</b></div><p>{{r.reason}}</p><div class="recommend-line"><el-select v-model="r.chosen"><el-option v-for="w in staff" :key="w.id" :label="w.name+(w.busy?'（执行中）':'')" :value="w.id"/></el-select><span>推荐 {{r.staff_name}} · 预计 {{r.eta}} 分钟</span><el-button type="primary" @click="confirmRec(r)" :loading="busy">确认派单</el-button></div><el-input v-if="r.chosen!==r.staff_id" v-model="r.reason" placeholder="请填写调整人员的原因"/></section><el-empty v-if="!recommendations.length" description="当前没有可确认的推荐" :image-size="70"/><div v-if="unassigned.length" class="info-banner compact"><span>另有 {{unassigned.length}} 项任务暂未分配，保留待确认。可在人员状态更新后重新计算。</span></div><template #footer><el-button @click="recOpen=false">关闭</el-button><el-button type="primary" plain @click="recommend" :loading="busy">重新计算推荐</el-button></template></el-dialog>

  <el-dialog v-model="actionOpen" :title="actionKind==='feedback'?'提交处置结果':actionKind==='reject'?'填写拒单原因':'核实并关闭事件'" width="min(520px,94vw)"><p class="muted">{{actionTask?.elder_name}} · {{actionTask?.title}}</p><el-form label-position="top"><el-form-item v-if="actionKind!=='reject'" label="核实结果"><el-select v-model="outcome" class="full"><el-option label="已确认安全" value="safe"/><el-option label="需要进一步帮助" value="needs_help"/><el-option label="未能联系" value="unreachable"/><el-option label="数据问题已核查" value="data_issue"/></el-select></el-form-item><el-form-item label="处理说明（至少两个字）"><el-input v-model="actionNote" type="textarea" :rows="4" placeholder="记录联系、走访或数据核查的实际结果"/></el-form-item></el-form><p class="muted">未解决的任务需继续跟进；关闭记录保留核实人与处置依据。</p><template #footer><el-button @click="actionOpen=false">取消</el-button><el-button type="primary" @click="sendAction" :loading="busy">确认提交</el-button></template></el-dialog>

  <el-drawer v-model="detail" :title="elderDetail?'老人档案与状态':'判断依据与处置记录'" size="min(660px,96vw)"><template v-if="elderDetail"><div class="detail-person"><span class="resident-avatar large">{{elderDetail.name.slice(0,1)}}</span><div><h2>{{elderDetail.name}}</h2><p>{{elderDetail.age}} 岁 · {{elderDetail.building}}</p></div><span class="risk-pill" :class="'level-'+elderDetail.level">{{levelNames[elderDetail.level]}}</span></div><section class="detail-section"><h3>日常与联系</h3><p>{{elderDetail.profile.routine}}</p><p>计划报平安：{{elderDetail.profile.checkin_hour}}:00 · {{elderDetail.contact}}</p><p>最近报平安：{{fmt(elderDetail.state.last_checkin)}}</p><p>数据来源：{{elderDetail.state.source}}</p><p>基线来源：{{elderDetail.profile.origin}} · {{elderDetail.profile.history_days}} 天</p><el-button type="primary" @click="openReport(elderDetail.id)">补充状态信息</el-button></section><section class="detail-section"><h3>活动判断依据</h3><p v-for="(e,i) in elderDetail.state.evidence" :key="i">{{e}}</p><p v-if="!elderDetail.state.evidence?.length" class="muted">尚未计算当前活动窗口，保留上报和报平安规则。</p></section><section class="detail-section"><h3>关联事件</h3><button v-for="i in incidents.filter(i=>i.elder_id===elderDetail?.id)" :key="i.id" class="detail-event" @click="showIncident(i)"><span class="risk-pill" :class="'level-'+i.level">{{levelNames[i.level]}}</span><b>{{i.title}}</b><span>{{i.status==='open'?'待处理':'已关闭'}}</span><el-icon><ArrowRight/></el-icon></button></section><section class="detail-section"><h3>最近上报</h3><el-timeline><el-timeline-item v-for="e in elderDetail.events" :key="e.id" :timestamp="fmt(e.received_at)"><b>{{kindNames[e.kind]||e.kind}}</b><p>{{e.source}} · {{e.payload.note||'已记录'}}</p><small v-if="e.payload.original_timestamp">原始窗口时间：{{fmt(e.payload.original_timestamp)}}</small></el-timeline-item></el-timeline></section></template><template v-else-if="selected"><span class="risk-pill" :class="'level-'+selected.level">{{levelNames[selected.level]}}</span><h2 class="detail-title">{{selected.elder_name}} · {{selected.title}}</h2><p class="muted">{{selected.incident_id}} · {{selected.state?stateNames[selected.state]:selected.status==='open'?'待处理':'已关闭'}}</p><section class="detail-section"><h3>为什么需要关注</h3><ul class="evidence-list"><li v-for="(e,i) in selected.evidence" :key="i">{{e}}</li></ul><div class="advice-box"><b>建议行动</b><p>{{selected.advice}}</p></div></section><section class="detail-section" v-if="selected.agent_runs?.length"><h3>Agent 建议与工作流</h3><AgentRunDetail v-for="run in selected.agent_runs" :key="run.id" :run="run" compact/></section><section class="detail-section" v-if="selected.feedback"><h3>处置结果</h3><div v-for="f in selected.feedback" :key="f.id" class="feedback-item"><b>{{({safe:'已确认安全',needs_help:'需要进一步帮助',unreachable:'未能联系',data_issue:'数据问题已核查'} as Row)[f.outcome]}}</b><p>{{f.note}}</p><small>{{f.actor}} · {{fmt(f.created)}}</small></div><p v-if="!selected.feedback.length" class="muted">尚无处置结果。</p></section><section class="detail-section" v-if="selected.audit"><h3>决策与操作留痕</h3><el-timeline><el-timeline-item v-for="a in selected.audit" :key="a.id" :timestamp="fmt(a.created)"><b>{{({risk_created:'风险事件已建立',risk_updated:'风险判断已更新',dispatch_confirmed:'社区确认派单',task_accept:'负责人接单',task_start:'开始处置',task_reject:'拒单，等待重新推荐',task_feedback:'提交处置反馈',task_followup:'继续跟进',task_close:'人工核实关闭',task_overdue:'任务超时提醒'} as Row)[a.action]||a.action}}</b><p>操作人：{{a.actor}}</p><p v-if="a.payload.note">{{a.payload.note}}</p><p v-if="a.payload.adjustment_reason">调整原因：{{a.payload.adjustment_reason}}</p><details><summary>查看决策快照</summary><pre>{{JSON.stringify(a.payload,null,2)}}</pre></details></el-timeline-item></el-timeline></section></template></el-drawer>

  <el-drawer v-model="noticeOpen" title="站内消息" size="min(440px,95vw)"><div v-for="n in notifications" :key="n.id" class="notification"><b>{{n.title}}</b><p>{{n.body}}</p><small>{{fmt(n.created)}}</small></div><el-empty v-if="!notifications.length" description="暂无站内消息"/></el-drawer>
 </div>
</template>
